  const res = spawnSync(bin, ['run', 'web/src/engine/format/corpus.test.ts'], {
    stdio: 'inherit',
    env: { ...process.env, CORPUS_FIXTURE: '1' },
  });
  process.exit(res.status ?? 1);
}

