describe('flowchart — shape→kind table (§8)', () => {
  it('maps every documented shape', () => {
    const { doc } = fromMermaid([
      'flowchart TD',
      'r(rounded)',
      's[rect]',
      'st([stadium])',
      'cy[(cyl)]',
      'ci((circle))',
      'asym>asym]',
      'rh{rhombus}',
    ].join('\n'));
    expect(kinds(doc)).toEqual({
      r: 'component', s: 'container', st: 'system_ext', cy: 'datastore',
      ci: 'person', asym: 'queue', rh: 'note',
    });
  });
