{"content":"// SPDX-License-Identifier: GPL-3.0-only
// Two-way sync state machine (M4-WP2) — FR-K2/K3/K5. Framework-free core:
// the CodeMirror adapter feeds textChanged/canvasChanged and renders
// snapshots; the machine owns all debouncing and state transitions.
//
// States: clean (buffer == canonical render) · editing (user typed, idle
// parse armed) · error (parse failed — buffer never clobbered, FR-K3) ·
// pending-apply (parsed doc handed to the canvas; applied() confirms).
// Canvas changes in non-clean states are queued (last wins) and flushed as a
// debounced re-render once the machine returns to clean — the user's buffer
// is never overwritten mid-edit. Valid text always converges to clean with
// the canonical print in the buffer (FR-K2/K4).
import { parsePDL } from '../../engine/format/parser';
import { printDoc } from '../../engine/format/printer';
import type { Diagnostic } from '../../engine/format/diagnostics';
import type { Doc } from '../../engine/model/types';

export type SyncState = 'clean' | 'editing' | 'error' | 'pending-apply';

export interface SyncSnapshot {
  state: SyncState;
  /** What the editor should display (buffer; canonical after apply). */
  codeText: string;
  /** Parse diagnostics of the current buffer (empty unless error). */
  diagnostics: Diagnostic[];
  /** Buffer differs from the last saved text (FR-K5 close prompt). */
  divergedFromSaved: boolean;
}

export interface SyncMachinePort {
  /** Debounced timers (code re-render 150 ms; idle parse 300 ms). */
  schedule(fn: () => void, ms: number): unknown;
  cancel(handle: unknown): void;
  /** Canvas update port: hand the parsed doc to the canvas. */
  apply(doc: Doc): void;
  codeDebounceMs?: number;
  idleMs?: number;
}

export interface SyncMachine {
  /** Reset for a newly opened file (timers cancelled, state clean). */
  loadFile(text: string): void;
  /** User typed; arms the idle parse. Echo-suppressed when equal to buffer. */
  textChanged(text: string): void;
  /** Canvas IR changed (palette, drag, properties). */
  canvasChanged(doc: Doc): void;
  /** Format-on-save hook: canonicalize + apply + markSaved (FR-K4). */
  formatNow(): void;
  /** Consumer confirms the canvas has applied the pending doc. */
  applied(): void;
  /** Consumer saved `text` (file content now matches). */
  markSaved(text: string): void;
  snapshot(): SyncSnapshot;
  subscribe(fn: (s: SyncSnapshot) => void): () => void;
}

const CODE_MS = 150;
const IDLE_MS = 300;

export function createSyncMachine(port: SyncMachinePort): SyncMachine {
  const codeMs = port.codeDebounceMs ?? CODE_MS;
  const idleMs = port.idleMs ?? IDLE_MS;

  let state: SyncState = 'clean';
  let buffer = '';
  let savedText = '';
  let diagnostics: Diagnostic[] = [];
  let codeTimer: unknown = null;
  let idleTimer: unknown = null;
  let pendingCanvas: Doc | null = null;
  const watchers = new Set<(s: SyncSnapshot) => void>();

  const snapshot = (): SyncSnapshot => ({
    state,
    codeText: buffer,
    diagnostics,
    divergedFromSaved: buffer !== savedText,
  });

  const emit = (): void => {
    const snap = snapshot();
    for (const fn of watchers) fn(snap);
  };

  const cancelAll = (): void => {
    if (codeTimer !== null) port.cancel(codeTimer);
    if (idleTimer !== null) port.cancel(idleTimer);
    codeTimer = null;
    idleTimer = null;
  };

  const renderFrom = (doc: Doc | null): void => {
    if (doc === null || printDoc(doc) === buffer) return;
    if (codeTimer !== null) port.cancel(codeTimer);
    codeTimer = port.schedule(() => {
      codeTimer = null;
      buffer = printDoc(doc);
      emit();
    }, codeMs);
  };

  const parseBuffer = (): { doc: Doc | null } => {
    const result = parsePDL(buffer);
    diagnostics = result.doc ? [] : result.diagnostics;
    return { doc: result.doc };
  };

  const runIdleParse = (): void => {
    idleTimer = null;
    const { doc } = parseBuffer();
    if (doc === null) {
      state = 'error'; // buffer untouched (FR-K3)
      emit();
      return;
    }
    state = 'pending-apply';
    emit();
    port.apply(doc);
  };

  const reachClean = (): void => {
    state = 'clean';
    if (pendingCanvas !== null) {
      const doc = pendingCanvas;
      pendingCanvas = null;
      emit();
      renderFrom(doc); // queued canvas change: debounced re-render
      return;
    }
    emit();
  };

  const armIdleParse = (): void => {
    if (idleTimer !== null) port.cancel(idleTimer);
    idleTimer = port.schedule(runIdleParse, idleMs);
  };

  return {
    loadFile(text) {
      cancelAll();
      pendingCanvas = null;
      buffer = text;
      savedText = text;
      diagnostics = [];
      state = 'clean';
      emit();
    },

    textChanged(text) {
      if (text === buffer) return; // echo suppression
      buffer = text;
      state = 'editing';
      diagnostics = [];
      armIdleParse();
      emit();
    },

    canvasChanged(doc) {
      if (state === 'clean') {
        renderFrom(doc);
        return;
      }
      pendingCanvas = doc; // flushed from reachClean (last wins)
    },

    formatNow() {
      cancelAll();
      const { doc } = parseBuffer();
      if (doc === null) {
        state = 'error';
        emit();
        return;
      }
      const canonical = printDoc(doc);
      const changed = canonical !== buffer || savedText !== canonical;
      buffer = canonical;
      pendingCanvas = null;
      if (changed) port.apply(doc);
      state = 'clean';
      emit();
    },

    applied() {
      if (state !== 'pending-apply') return;
      if (idleTimer !== null) {
        port.cancel(idleTimer);
        idleTimer = null;
      }
      buffer = printDoc(parseBuffer().doc ?? parsePDL(buffer).doc!);
      reachClean();
    },

    markSaved(text) {
      savedText = text;
      emit();
    },

    snapshot,
    subscribe(fn) {
      watchers.add(fn);
      fn(snapshot());
      return () => watchers.delete(fn);
    },
  };
}
