{"content":"// SPDX-License-Identifier: GPL-3.0-only
// Code view editor (M4-WP1/WP2/WP3) — thin CodeMirror 6 adapter over the
// SyncMachine (web/src/ui/codeview/sync.ts) and the engine diagnostics.
// The component owns no sync logic: it forwards editor→machine textChanged,
// machine→editor buffer writes (echo-suppressed via the machine), and maps
// parser line:col diagnostics to CM lint marks + a problems list (FR-K3).
import { useEffect, useRef, useState } from 'preact/hooks';
import { EditorState } from '@codemirror/state';
import { EditorView, keymap, lineNumbers, highlightActiveLine, highlightActiveLineGutter } from '@codemirror/view';
import { defaultKeymap, history, historyKeymap } from '@codemirror/commands';
import { searchKeymap, highlightSelectionMatches } from '@codemirror/search';
import { linter, type Diagnostic as CmDiagnostic, lintGutter } from '@codemirror/lint';
import { createSyncMachine, type SyncMachine, type SyncSnapshot } from './sync';
import { pdlStreamLanguage } from './pdlMode';
import { pcTheme, pcHighlightExtension } from './cmTheme';

export interface CodeEditorProps {
  initialText: string;
  /** Canvas IR changed → machine.canvasChanged (wired by the App shell). */
  onApply?: (text: string) => void;
  /** Consumer saved the buffer (autosave/format-on-save). */
  onSaved?: () => void;
  /** Expose the machine to the parent (format button, problems panel). */
  machineRef?: { current: SyncMachine | null };
}

/** Editor pane + problems panel for the active file. */
export function CodeEditor({ initialText, onApply, onSaved, machineRef }: CodeEditorProps) {
  const host = useRef<HTMLDivElement | null>(null);
  const view = useRef<EditorView | null>(null);
  const machine = useRef<SyncMachine | null>(null);
  const [snap, setSnap] = useState<SyncSnapshot | null>(null);
  const applyRef = useRef(onApply);
  applyRef.current = onApply;

  if (machine.current === null) {
    machine.current = createSyncMachine({
      schedule: (fn, ms) => setTimeout(fn, ms) as unknown as number,
      cancel: (id) => clearTimeout(id as unknown as ReturnType<typeof setTimeout>),
      apply: (doc) => applyRef.current?.(JSON.parse(JSON.stringify(doc))),
    });
  }
  if (machineRef) machineRef.current = machine.current;

  // Machine → editor buffer (echo-suppressed inside the machine).
  useEffect(() => {
    const m = machine.current!;
    const unsub = m.subscribe((s) => {
      setSnap(s);
      const v = view.current;
      if (v !== null && v.state.doc.toString() !== s.codeText) {
        v.dispatch({ changes: { from: 0, to: v.state.doc.length, insert: s.codeText } });
      }
    });
    m.loadFile(initialText);
    return unsub;
  }, [initialText]);

  // Editor construction (once).
  useEffect(() => {
    const m = machine.current!;
    const lintSource = (): CmDiagnostic[] =>
      m.snapshot().diagnostics.map((d) => ({
        from: posToOffset(m.snapshot().codeText, d.line, d.col),
        to: Math.min(posToOffset(m.snapshot().codeText, d.line, d.col) + 1, m.snapshot().codeText.length),
        severity: d.severity === 'warning' ? 'warning' : 'error',
        message: `${d.code}: ${d.message}`,
      }));

    const state = EditorState.create({
      doc: initialText,
      extensions: [
        lineNumbers(),
        highlightActiveLine(),
        highlightActiveLineGutter(),
        history(),
        highlightSelectionMatches(),
        keymap.of([...defaultKeymap, ...historyKeymap, ...searchKeymap]),
        pdlStreamLanguage,
        pcTheme,
        pcHighlightExtension,
        lintGutter(),
        linter(lintSource),
        EditorView.updateListener.of((u) => {
          if (u.docChanged) m.textChanged(u.state.doc.toString());
        }),
      ],
    });
    const v = new EditorView({ state, parent: host.current! });
    view.current = v;
    return () => {
      v.destroy();
      view.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- constructed once
  }, []);

  return (
    <div class="code-view" data-testid="code-view" data-sync-state={snap?.state ?? 'clean'}>
      <div class="code-editor-host" ref={host} />
      <ProblemsPanel snapshot={snap} />
    </div>
  );
}

/** line:col (1-based) → string offset for CM marks (WP3). */
export function posToOffset(text: string, line: number, col: number): number {
  const lines = text.split('\n');
  let off = 0;
  for (let i = 0; i < line - 1 && i < lines.length; i++) off += lines[i].length + 1;
  const lineText = lines[Math.min(line - 1, lines.length - 1)] ?? '';
  return Math.min(off + Math.max(0, col - 1), off + lineText.length);
}

/** FR-K3 problems panel: list of diagnostics, click → focus the line. */
export function ProblemsPanel({ snapshot }: { snapshot: SyncSnapshot | null }) {
  if (snapshot === null || snapshot.diagnostics.length === 0) {
    return (
      <div class="problems" data-testid="problems-empty">
        {snapshot?.state === 'error' ? 'no diagnostics' : ''}
      </div>
    );
  }
  return (
    <div class="problems" data-testid="problems" role="listbox" aria-label="Problems">
      {snapshot.diagnostics.map((d, i) => (
        <button
          key={i}
          type="button"
          role="option"
          class={`problem problem-${d.severity}`}
          data-testid="problem-item"
          aria-selected="false"
          onClick={() => focusLine(d.line)}
        >
          <span class="problem-loc">{d.line}:{d.col}</span>
          <span class="problem-code">{d.code}</span>
          <span class="problem-msg">{d.message}</span>
        </button>
      ))}
    </div>
  );
}

function focusLine(line: number): void {
  const el = document.querySelector<HTMLElement>(`.cm-line:nth-child(${line})`);
  el?.scrollIntoView({ block: 'center' });
}
