export const pdlStreamLanguage = StreamLanguage.define<{
  inBlockComment: boolean;
}>({
  token(stream, state) {
    if (state.inBlockComment) return skipBlockComment(stream, state);
    return matchToken(stream, state);
  },
  startState: () => ({ inBlockComment: false }),
  blankLine: (_state) => {},
  copyState: (state) => ({ inBlockComment: state.inBlockComment }),
});

function skipBlockComment(
  stream: { skipTo(s: string): boolean; skipToEnd(): void; pos: number },
  state: { inBlockComment: boolean },
): string {
  if (stream.skipTo('*/')) {
    stream.pos += 2; // through */
    state.inBlockComment = false;
  } else {
    stream.skipToEnd();
  }
  return 'comment';
}

function matchToken(
  stream: { match(p: string | RegExp, consume?: boolean): boolean; skipTo(s: string): boolean; skipToEnd(): void; next(): boolean; current(): string },
  state: { inBlockComment: boolean },
): string | null {
  if (stream.match('/*')) {
    state.inBlockComment = true;
    return 'comment';
  }
  if (stream.match('#') || stream.match('//')) {
    stream.skipToEnd();
    return 'comment';
  }
  if (stream.match('"')) return matchString(stream);
  if (stream.match(/#[0-9a-fA-F]{3}\b|#[0-9a-fA-F]{6}\b/)) return 'number';
  if (stream.match(/<-?>|-\.[^>]*->|--[^>-]*->|=>|-->|->|---/)) return 'keyword';
  if (stream.match(/[0-9]+(\.[0-9]+)?/)) return 'number';
  if (stream.match(/[a-zA-Z_][a-zA-Z0-9_-]*/)) {
    return KEYWORDS.has(stream.current()) ? 'keyword' : 'variableName';
  }
  if (stream.match(/[{}():,]/)) return 'operator';
  stream.next();
  return null;
}

function matchString(stream: { skipTo(s: string): boolean; skipToEnd(): void; next(): boolean }): string {
  if (stream.skipTo('"')) {
    stream.next();
  } else {
    stream.skipToEnd();
  }
  return 'string';
