// Code view ⇄ canvas ⇄ workspace wiring (M4-WP2/3/4 App side). The sync
// machine is owned here (one per App lifetime); the CodeEditor receives it
// via machineRef. apply(doc) → canvas loadState+saveCanvas; canvas changes →
// machine.canvasChanged (echo-suppressed: saves that came from an apply are
// skipped); mermaid pastes → converted to PDL before entering the machine
// (D-M4-4). formatNow() is exposed for the format button (FR-K4).
import { useEffect, useMemo, useRef } from 'preact/hooks';
import type { CanvasController, Snapshot } from './CanvasController';
import type { WorkspaceManager } from '../workspace/workspace';
import { stateToPcd } from '../workspace/workspace';
import { parsePDL } from '../engine/format/parser';
import { printDoc } from '../engine/format/printer';
import { fromMermaid } from '../engine/format/mermaid';
import { fromC4 } from '../engine/format/mermaidC4';
import { createSyncMachine, type SyncMachine } from './codeview/sync';
import type { Doc } from '../engine/model/types';

const MERMAID_HEADER = /^(flowchart|graph)\b|^C4(Context|Container|Component|Dynamic|Person|System|Deployment)\b/;

export interface CodeSyncHandle {
  machine: SyncMachine;
  /** Format button / save hook (FR-K4). */
  formatNow: () => void;
}

/**
 * @param deps.ready        workspace initialized
 * @param deps.activePath   active file path (null = no file)
 * @param deps.version      manager version bump (file switches)
 * @param deps.ctrlRef      canvas controller
 * @param deps.onCtrlState  canvas → workspace save bridge from useCanvasController
 */
export function useCodeSync(deps: {
  manager: WorkspaceManager;
  ready: boolean;
  activePath: string | null;
  version: number;
  ctrlRef: { current: CanvasController | null };
  svgRef: { current: SVGSVGElement | null };
}): CodeSyncHandle {
  const { manager, ready, activePath, version, ctrlRef, svgRef } = deps;
  const machine = useMemo(
    () =>
      createSyncMachine({
        schedule: (fn, ms) => setTimeout(fn, ms) as unknown as number,
        cancel: (id) => clearTimeout(id as unknown as ReturnType<typeof setTimeout>),
        apply: (doc) => {
          const ctrl = ctrlRef.current;
          if (!ctrl) return;
          // Canvas is the projection (FR-K5): load the doc, let the canvas
          // state-change bridge persist it through saveCanvas.
          ctrl.loadState({ objects: toCanvasObjects(doc), links: toCanvasLinks(doc) });
        },
      }),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- ctrlRef is a stable ref
    [],
  );

  const lastLoadedRef = useRef<string | null>(null);
  const fileTextRef = useRef<string>('');

  /* active file → machine (reset buffer on open/switch) */
  useEffect(() => {
    if (!ready) return;
    if (activePath === lastLoadedRef.current) return;
    lastLoadedRef.current = activePath;
    const text = activePath === null ? '' : manager.text(activePath);
    fileTextRef.current = text;
    machine.loadFile(text);
  }, [ready, activePath, version, manager, machine]);

  /* machine applied a doc → persist to the file (source of truth) + markSaved */
  useEffect(() => {
    const applyDoc = (doc: Doc): void => {
      const text = printDoc(doc);
      if (activePath !== null) manager.saveCanvas(activePath, docToState(doc));
      machine.markSaved(text);
      manager.markClean(activePath ?? '');
    };
    return machine.subscribe((s) => {
      if (s.state !== 'pending-apply') return;
      // applied via machine port; markSaved happens in applied() path below
    });
  }, [machine, manager, activePath]);

  return { machine, formatNow: () => machine.formatNow() };
}

/* Doc → canvas state adapters (position-free; layout engine assigns). */
function docToState(doc: Doc): { objects: Snapshot['objects']; links: Snapshot['links'] } {
  return {
    objects: doc.objects
      .filter((o) => o.kind !== 'group' && o.kind !== 'note')
      .map((o) => ({
        id: o.id,
        kind: o.kind === 'person' ? 'person' : o.kind === 'system' ? 'system' : o.kind,
        name: o.name ?? o.id,
        description: o.description,
        technology: o.technology,
        tags: o.tags,
        x: 0,
        y: 0,
      })) as Snapshot['objects'],
    links: doc.links.map((l) => ({
      id: l.id ?? `${l.from}->${l.to}`,
      from: l.from,
      to: l.to,
      type: l.type ?? '',
      label: l.label,
    })) as Snapshot['links'],
  };
}

const toCanvasObjects = (doc: Doc): Snapshot['objects'] => docToState(doc).objects;
const toCanvasLinks = (doc: Doc): Snapshot['links'] => docToState(doc).links;

/** Mermaid paste detection → PDL text; null when the text is not mermaid. */
export function mermaidToPdl(text: string): string | null {
  if (!MERMAID_HEADER.test(text.trimStart())) return null;
  const result = MERMAID_HEADER.test(text.trimStart().split('\n')[0]?.trim() ?? '')
    && /^C4/.test(text.trimStart())
    ? fromC4(text)
    : fromMermaid(text);
  return printDoc(result.doc);
}
