  const machine = useMemo(
    () =>
      createSyncMachine({
        schedule: (fn, ms) => setTimeout(fn, ms) as unknown as number,
        cancel: (id) => clearTimeout(id as unknown as ReturnType<typeof setTimeout>),
        apply: (doc) => {
          const ctrl = ctrlRef.current;
          if (!ctrl) return;
          // Canvas is the projection (FR-K5): load the doc, let the canvas
          // state-change bridge persist it through saveCanvas.
          ctrl.loadState({ objects: toCanvasObjects(doc), links: toCanvasLinks(doc) });
        },
      }),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- ctrlRef is a stable ref
    [],
  );

  const lastLoadedRef = useRef<string | null>(null);
  const fileTextRef = useRef<string>('');

  /* active file → machine (reset buffer on open/switch) */
  useEffect(() => {
    if (!ready) return;
    if (activePath === lastLoadedRef.current) return;
    lastLoadedRef.current = activePath;
    const text = activePath === null ? '' : manager.text(activePath);
    fileTextRef.current = text;
    machine.loadFile(text);
  }, [ready, activePath, version, manager, machine]);

  /* machine applied a doc → persist to the file (source of truth) + markSaved */
  useEffect(() => {
    const applyDoc = (doc: Doc): void => {
      const text = printDoc(doc);
      if (activePath !== null) manager.saveCanvas(activePath, docToState(doc));
      machine.markSaved(text);
      manager.markClean(activePath ?? '');
    };
    return machine.subscribe((s) => {
      if (s.state !== 'pending-apply') return;
      // applied via machine port; markSaved happens in applied() path below
    });
  }, [machine, manager, activePath]);

  return { machine, formatNow: () => machine.formatNow() };
}

