      })) as Snapshot['objects'],
    links: doc.links.map((l) => ({
      id: l.id ?? `${l.from}->${l.to}`,
      from: l.from,
      to: l.to,
      type: l.type ?? '',
      label: l.label,
    })) as Snapshot['links'],
  };
}

const toCanvasObjects = (doc: Doc): Snapshot['objects'] => docToState(doc).objects;
const toCanvasLinks = (doc: Doc): Snapshot['links'] => docToState(doc).links;","operation":"replace","path":"web/src/ui/useCodeSync.ts"}

