     1  // SPDX-License-Identifier: GPL-3.0-only
     2  // Sync state machine tests (M4-WP2, test-first) — FR-K2/K3/K5.
     3  // Exhaustive transition table over states clean/editing/error/pending-apply:
     4  //
     5  //   clean    -textChanged(new)→  editing      (idle parse scheduled)
     6  //   clean    -textChanged(echo)→ clean        (echo suppressed, no timer)
     7  //   clean    -canvasChanged→    clean         (code re-render debounced 150 ms)
     8  //   editing  -textChanged→      editing       (idle rescheduled)
     9  //   editing  -idle parse OK→    pending-apply (apply requested; applied() → clean)
    10  //   editing  -idle parse FAIL→  error         (buffer never clobbered)
    11  //   error    -textChanged→      editing
    12  //   error    -idle parse OK→    pending-apply
    13  //   pending-apply -textChanged→ editing
    14  //   *        -canvasChanged(non-clean)→ queued, flushed on clean (last wins)
    15  //   *        -formatNow OK→     clean (+ apply + markSaved)
    16  //   *        -formatNow FAIL→   error
    17  //   *        -loadFile→         clean (timers cancelled, no stray apply)
    18  //
    19  // Property: any sequence of valid texts converges to clean with
    20  // parse(print(doc)) equal to the applied doc (FR-K2 "valid text converges").
    21  import { describe, expect, it, vi } from 'vitest';
    22  import { createSyncMachine, type SyncMachine, type SyncSnapshot } from './sync';
    23  import { parsePDL } from '../../engine/format/parser';
    24  import { printDoc } from '../../engine/format/printer';
    25  import type { Doc } from '../../engine/model/types';
    26  
    27  /** Deterministic scheduler: timers fire only when tick()en. */
    28  class FakeScheduler {
    29    readonly pending = new Map<number, { fn: () => void; ms: number }>();
    30    private next = 1;
    31    readonly scheduled: { ms: number }[] = [];
    32    schedule(fn: () => void, ms: number): number {
    33      const id = this.next++;
    34      this.pending.set(id, { fn, ms });
    35      this.scheduled.push({ ms });
    36      return id;
    37    }
    38    cancel(id: number): void {
    39      this.pending.delete(id);
    40    }
    41    /** Fire every pending timer (in schedule order, cascading). */
    42    flush(): void {
    43      while (this.pending.size > 0) {
    44        for (const { fn } of [...this.pending.values()]) fn();
    45      }
    46    }
    47    tickAll(ms: number): void {
    48      for (const [id, t] of [...this.pending]) {
    49        if (t.ms <= ms) {
    50          this.pending.delete(id);
    51          t.fn();
    52        }
    53      }
    54    }
    55  }
    56  
    57  const PDL_A = 'pcd 1.0\n\nsystem a "A" {\n}\n';
    58  const PDL_B = 'pcd 1.0\n\nsystem b "B" {\n}\n';
    59  const BAD = 'pcd 1.0\nsystem';
