    68  const rig = (initial = PDL_A): Rig => {
    69    const sched = new FakeScheduler();
    70    const appliedDocs: Doc[] = [];
    71    const snapshots: SyncSnapshot[] = [];
    72    const machine = createSyncMachine({
    73      schedule: (fn, ms) => sched.schedule(fn, ms),
    74      cancel: (id) => sched.cancel(id as number),
    75      apply: (doc) => appliedDocs.push(doc),
    76      codeDebounceMs: 150,
    77      idleMs: 300,
    78    });
    79    machine.subscribe((s) => snapshots.push(s));
    80    machine.loadFile(initial);
    81    return { sched, machine, appliedDocs, snapshots };
    82  };
    83  
    84  const state = (m: SyncMachine) => m.snapshot().state;
    85  
    86  describe('initial state', () => {
    87    it('loadFile → clean, code shows the file text, not diverged', () => {
    88      const { machine } = rig();
    89      const snap = machine.snapshot();
    90      expect(snap.state).toBe('clean');
    91      expect(snap.codeText).toBe(PDL_A);
    92      expect(snap.diagnostics).toEqual([]);
    93      expect(snap.divergedFromSaved).toBe(false);
    94    });
    95  });
