   102      expect(machine.snapshot().codeText).toBe(PDL_B); // buffer preserved
   103      sched.tickAll(300);
   104      expect(state(machine)).toBe('pending-apply');
   105      expect(appliedDocs).toHaveLength(1);
   106      machine.applied();
   107      expect(state(machine)).toBe('clean');
   108      // buffer converges to the canonical print of the applied doc (FR-K4)
   109      expect(machine.snapshot().codeText).toBe(printDoc(parsePDL(PDL_B).doc!));
   110      // the file on disk still holds the old content until autosave runs
   111      expect(machine.snapshot().divergedFromSaved).toBe(true);
   112      machine.markSaved(machine.snapshot().codeText);
   113      expect(machine.snapshot().divergedFromSaved).toBe(false);
   114    });
