    await mountReady();
    // let the async init chain (storage fallback → init → ready) settle so
    // the code view is wired to the active file before interacting
    await act(async () => {
      await new Promise((r) => setTimeout(r, 0));
    });
    const view = EditorView.findFromDOM(document.querySelector('.cm-editor') as HTMLElement)!;
    // type garbage (buffer diverges; idle parse has not fired yet → editing)
    act(() => {
      view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: 'pcd 1.0\nsystem' } });
