    23    resolveImport?: (path: string) => string | null;
    24  }
    25  
    26  const SHAPE: Record<Obj['kind'], (label: string) => string> = {
    27    person: (l) => `((${l}))`,
    28    system: (l) => `[${l}]`,
    29    container: (l) => `[${l}]`,
    30    system_ext: (l) => `([${l}])`,
    31    component: (l) => `(${l})`,
    32    datastore: (l) => `[(${l})]`,
