{"command":"cat > e2e/zz-probe2.spec.ts <<'EOF'
import { expect, test } from '@playwright/test';

test('probe5: state across reloads (does drop work persist?)', async ({ page }) => {
  await page.goto('/');
  const canvas = page.getByTestId('canvas');
  await expect(canvas).toBeVisible();
  const box = (await canvas.boundingBox()) ?? { x: 0, y: 0, width: 800, height: 600 };
  const d = { kind: 'palette-person', x: 120, y: 160 };
  const item = page.getByTestId(d.kind);
  const ib = (await item.boundingBox()) ?? { x: 0, y: 0, width: 0, height: 0 };
  await page.mouse.move(ib.x + ib.width / 2, ib.y + ib.height / 2);
  await page.mouse.down();
  await page.mouse.move(box.x + d.x, box.y + d.y, { steps: 8 });
  await page.mouse.up();
  await expect(canvas.locator('g.pc-obj')).toHaveCount(1);
  await page.waitForTimeout(600); // let autosave flush
  const t1 = await page.evaluate(() => document.querySelector('.pc-obj')?.getAttribute('transform'));
  console.log('OBJ T1', t1);
  await page.reload();
  await expect(canvas).toBeVisible();
  await page.waitForTimeout(500);
  const n = await page.evaluate(() => document.querySelectorAll('.pc-obj').length);
  const t2 = await page.evaluate(() => document.querySelector('.pc-obj')?.getAttribute('transform'));
  console.log('AFTER RELOAD count', n, 'transform', t2);
});
EOF
npx playwright test e2e/zz-probe2.spec.ts --project=chromium 2>&1 | grep -E "OBJ T1|AFTER RELOAD|passed|failed"","timeout":120}

{"command":"cat > e2e/zz-probe2.spec.ts <<'EOF'
import { expect, test } from '@playwright/test';

test('probe6: single test — two goto/reloads — when does reuse break?', async ({ page }) => {
  await page.goto('/');
  let canvas = page.getByTestId('canvas');
  await expect(canvas).toBeVisible();
  let box = (await canvas.boundingBox()) ?? { x: 0, y: 0, width: 800, height: 600 };
  const drop = async (x: number, y: number) => {
    const item = page.getByTestId('palette-person');
    const ib = (await item.boundingBox()) ?? { x: 0, y: 0, width: 0, height: 0 };
    await page.mouse.move(ib.x + ib.width / 2, ib.y + ib.height / 2);
    await page.mouse.down();
    await page.mouse.move(box.x + x, box.y + y, { steps: 8 });
    await page.mouse.up();
  };
  await drop(120, 160);
  await expect(canvas.locator('g.pc-obj')).toHaveCount(1);
  await page.waitForTimeout(500);

  // second workspace state in the SAME page context via reload
  await page.reload();
  await expect(canvas).toBeVisible();
  box = (await canvas.boundingBox()) ?? box;
  await drop(120, 160);
  const c2 = await page.locator('g.pc-obj').count();
  console.log('SAME-PAGE 2ND COUNT', c2);

  // NEW page in same context (storage shared)
  const p2 = await page.context().newPage();
  await p2.goto('/');
  const c3 = await p2.locator('g.pc-obj').count();
  console.log('NEW-PAGE COUNT (should be restored objects)', c3);
  await p2.close();
});
EOF
npx playwright test e2e/zz-probe2.spec.ts --project=chromium 2>&1 | grep -E "SAME-PAGE|NEW-PAGE|passed|failed"","timeout":120}

