    await page.mouse.down();
    await page.mouse.move(box.x + d.x, box.y + d.y, { steps: 8 });
    await page.mouse.up();
  }
  await expect(canvas.locator('g.pc-obj')).toHaveCount(3);
  await page.mouse.click(box.x + 120, box.y + 160);
  const halo = canvas.locator('.pc-halo[data-side="right"]').first();
  await expect(halo).toBeVisible();
  const hb = (await halo.boundingBox()) ?? { x: 0, y: 0, width: 0, height: 0 };
  await page.mouse.move(hb.x + hb.width / 2, hb.y + hb.height / 2);
  await page.mouse.down();
  await page.mouse.move(box.x + 340, box.y + 160, { steps: 6 });
  await page.mouse.up();
  await expect(canvas.locator('g.pc-link')).toHaveCount(1);
  await page.mouse.click(box.x + 420, box.y + 160);
  const halo2 = canvas.locator('.pc-halo[data-side="bottom"]').first();
  await expect(halo2).toBeVisible();
  const hb2 = (await halo2.boundingBox()) ?? { x: 0, y: 0, width: 0, height: 0 };
  await page.mouse.move(hb2.x + hb2.width / 2, hb2.y + hb2.height / 2);
  await page.mouse.down();
  await page.mouse.move(box.x + 420, box.y + 390, { steps: 6 });
  await page.mouse.up();
  await expect(canvas.locator('g.pc-link')).toHaveCount(2);
  // now the S1 props click:
  await page.evaluate(() => {
    const w = window as unknown as { __sel?: string[] };
    w.__sel = [];
    setInterval(() => {
      const sel = [...document.querySelectorAll('g.pc-obj.pc-selected text')].map((t) => t.textContent);
      const name = (document.querySelector('[data-testid="prop-name"]') as HTMLInputElement | null)?.value;
      w.__sel!.push(`sel=${JSON.stringify(sel)} name=${name}`);
    }, 80);
  });
  await page.mouse.click(box.x + 420, box.y + 160);
  await page.waitForTimeout(2500);
  console.log('TIMELINE\n' + (await page.evaluate(() => (window as unknown as { __sel: string[] }).__sel)).slice(0, 32).join('\n'));
});
