it('probe', () => {
  const svg = document.createElementNS(SVG_NS, 'svg') as unknown as SVGSVGElement;
  const world = document.createElementNS(SVG_NS, 'g');
  world.setAttribute('class', 'pc-world');
  svg.appendChild(world);
  const g = document.createElementNS(SVG_NS, 'g');
  g.setAttribute('class', 'pc-link');
  g.setAttribute('data-id', 'ab');
  const p = document.createElementNS(SVG_NS, 'path');
  p.setAttribute('class', 'pc-route');
  p.setAttribute('d', 'M0 0 L100 0');
  g.appendChild(p);
  world.appendChild(g);
  const calls: unknown[] = [];
  const player: AnimPlayer = {
    animate: (el, kf, opts): AnimHandle => {
      calls.push([el, kf, opts]);
      return { cancel: () => {} };
    },
  };
  const beat: Beat = {
    index: 2,
    kind: 'msg',
    title: '',
    actors: ['a', 'b'],
    links: [{ linkId: 'ab', from: 'a', to: 'b', flipped: false }],
    dim: [],
    delayMs: 2500,
  };
  const anim = new FlowAnimator(svg, {
    player,
    geometry: { length: () => 100, pointAt: (_e, d) => ({ x: d, y: 0 }) },
  });
  anim.play(beat, { rectOf: () => null });
  const layer = svg.querySelector('.pc-anim-layer');
  console.log('layer:', layer !== null, layer?.childElementCount);
  console.log('layer html:', (layer as Element | null)?.outerHTML?.slice(0, 200));
  console.log('token via svg:', svg.querySelector('.pc-token') !== null);
  console.log('token via layer:', layer?.querySelector('.pc-token') !== null);
  console.log('calls:', calls.length);
  expect(true).toBe(true);
});
