{"content":"// SPDX-License-Identifier: GPL-3.0-only
// Pure flow-document editing (M5-WP4). The flow editor is "just another text
// producer": it parses the file text, mutates the doc's flows, and prints —
// the resulting text goes through the M4 sync machine (machine.textChanged)
// so persistence, canvas projection, and the sync chip stay honest (D-M4-6).
//
// Step addressing: a path is a list of child indices walking containers —
// [i] top-level step i; alt at i: [i, branch, step, ...]; par at i:
// [i, lane, step, ...]. Mutators operate in place on a (caller-owned) Flow —
// retext() owns the parse/clone/print lifecycle.
import type { Branch, Doc, Flow, FlowStep } from '../../engine/model/types';

type StepList = FlowStep[];

/** Resolve the list that holds the step at `path`, plus the last index. */
function locate(flow: Flow, path: number[]): { list: StepList } | null {
  if (path.length === 0) return null;
  const i = path[0];
  if (i === undefined) return null;
  const step = flow.steps[i];
  if (step === undefined) return null;
  if (path.length === 1) return { list: flow.steps };
  const k = path[1];
  if (k === undefined) return null;
  if (step.type === 'alt') {
    const branch = step.branches[k];
    if (branch === undefined) return null;
    return descend(branch.steps, path, 2);
  }
  if (step.type === 'par') {
    const lane = step.lanes[k];
    if (lane === undefined) return null;
    return descend(lane, path, 2);
  }
  return null;
}

function descend(list: StepList, path: number[], depth: number): { list: StepList } | null {
  if (path.length === depth) return { list };
  const i = path[depth];
  if (i === undefined) return null;
  const step = list[i];
  if (step === undefined) return null;
  const k = path[depth + 1];
