import type { Branch, Doc, Flow, FlowStep } from '../../engine/model/types';

type StepList = FlowStep[];

/** Fetch the step at `path` (child indices through alt branches / par lanes). */
export function getAt(flow: Flow, path: number[]): FlowStep | null {
  if (path.length === 0) return null;
  const i = path[0];
  const first = i === undefined ? undefined : flow.steps[i];
  if (first === undefined) return null;
  if (path.length === 1) return first;
  const k = path[1];
  if (k === undefined) return null;
  if (first.type === 'alt') return getIn(first.branches[k]?.steps ?? [], path, 2);
  if (first.type === 'par') return getIn(first.lanes[k] ?? [], path, 2);
  return null;
}

function getIn(list: StepList, path: number[], depth: number): FlowStep | null {
  if (path.length === depth) return list[path[depth - 1] ?? -1] ?? null;
  const i = path[depth];
  const step = i === undefined ? undefined : list[i];
  if (step === undefined) return null;
  const k = path[depth + 1];
  if (k === undefined) return null;
  if (step.type === 'alt') return getIn(step.branches[k]?.steps ?? [], path, depth + 2);
  if (step.type === 'par') return getIn(step.lanes[k] ?? [], path, depth + 2);
  return null;
}

/** The list holding the step at `path` (parent container), for mutators. */
function holder(flow: Flow, path: number[]): { list: StepList; index: number } | null {
  if (path.length === 0) return null;
  const last = path[path.length - 1];
  if (last === undefined) return null;
  const parentPath = path.slice(0, -1);
  if (parentPath.length === 0) return { list: flow.steps, index: last };
