    const branch = parent.branches[k ?? -1];
    return branch === undefined ? null : { list: branch.steps, index: last };
  }
  if (parent.type === 'par') {
    const lane = parent.lanes[k ?? -1];
    return lane === undefined ? null : { list: lane, index: last };
  }
  return null;
