/** Pre-order listing for the editor UI (row rendering + drag context). */
export interface FlatStep {
  path: number[];
  step: FlowStep;
  depth: number;
  branch?: string;
  lane?: number;
}

export function flatSteps(flow: Flow): FlatStep[] {
  const out: FlatStep[] = [];
