{"content":"// SPDX-License-Identifier: GPL-3.0-only
// Play-mode transport (M5-WP5, PLAN §7; SPEC FR-F2/F3): drives the
// FlowAnimator + CameraController along a playback plan. Owns the beat index,
// alt-branch choices, goto frame stack (cross-file, FR-F2), narration text,
// and the auto-advance timer — all timing through the injected Clock, all
// visuals through the injected animator/camera (deterministic tests).
//
// Frame stack: goto pushes { plan, index, file, gotoBeat }; finishing a frame
// pops — `return end` (default) resumes AFTER the goto step, `return here`
// replays the goto beat and pauses (loop checkpoint, FILE-FORMAT §6).
import { useCallback, useMemo, useRef, useState } from 'preact/hooks';
import { buildPlan, collectAlts, type AltInfo, type PlaybackPlan } from '../../engine/flows/plan';
import { parsePDL } from '../../engine/format/parser';
import type { Beat, BeatCtx, FlowAnimator } from '../../engine/anim/engine';
import type { CameraController } from '../../engine/anim/camera';
import type { Clock } from '../../engine/anim/ports';
import type { Rect } from '../../engine/render/viewport';

export interface FlowRects {
  /** World rect per object id (camera target + ring placement). */
  rectOf(id: string): Rect | null;
}

export interface FlowPlayerDeps {
  /** File text lookup (workspace manager adapter). */
  textOf(path: string): string | null;
  /** Navigate to a file (goto cross-file). */
  openFile(path: string): void;
  animator: FlowAnimator;
  camera: CameraController;
  clock: Clock;
  reducedMotion: boolean;
}

interface Frame {
  plan: PlaybackPlan;
  index: number; // 0-based
  file: string;
  /** Parent frame's goto beat position for the return jump. */
  returnTo: number; // 0-based index into the PARENT plan (-1 = root)
  retHere: boolean;
}

export interface FlowPlayerState {
  status: 'idle' | 'playing' | 'paused' | 'ended';
  narration: string;
  breadcrumb: string[]; // titles of goto frames above the current one
  awaitingChoice: AltInfo | null;
  progress: { index: number; total: number } | null;
}

const EMPTY: FlowPlayerState = {
  status: 'idle',
  narration: '',
  breadcrumb: [],
  awaitingChoice: null,
  progress: null,
};

export function useFlowPlayer(deps: FlowPlayerDeps) {
  const { textOf, openFile, animator, camera, clock } = deps;
  const [state, setState] = useState<FlowPlayerState>(EMPTY);
  const stack = useRef<Frame[]>([]);
  const choices = useRef<Record<string, number>>({});
  const timer = useRef<number | null>(null);
  /** 1-based index chosen by stepTo while idle-ish; -1 = none. */
  const parked = useRef<number>(-1);

  const cancelTimer = (): void => {
    if (timer.current !== null) clock.cancel(timer.current);
    timer.current = null;
  };

  const frame = (): Frame => {
    const f = stack.current.at(-1);
    if (f === undefined) throw new Error('playback frame stack empty');
    return f;
  };

  const ctx = useMemo<BeatCtx>(
    () => ({
      rectOf: () => null, // replaced per-play by owner-supplied provider
    }),
    [],
  );
  const rectsRef = useRef<FlowRects>({ rectOf: () => null });

  const total = (): number => frame().plan.beats.length;

  const publish = (patch: Partial<FlowPlayerState>): void => {
    setState((s) => ({ ...s, ...patch }));
  };

  const narrate = (beat: Beat): string => beat.title;

  const progressOf = (f: Frame): { index: number; total: number } => ({
    index: f.index + 1,
    total: f.plan.beats.length,
  });

  /** Execute the beat at the current frame index. */
  const runBeat = (): void => {
    const f = frame();
    const beat = f.plan.beats[f.index];
    if (beat === undefined) return;
    animator.play(beat, rectsRef.current as BeatCtx);
    camera.focus(
      beat.actors.map((id) => rectsRef.current.rectOf(id)).filter((r): r is Rect => r !== null),
      { x: 0, y: 0, k: 1 },
    );
    publish({
      narration: narrate(beat),
      progress: progressOf(f),
      awaitingChoice: null,
    });
    if (beat.kind === 'alt') {
      const known = collectAlts(f.plan.beats === undefined ? ({ steps: [] } as never) : (null as never));
      void known;
      awaitChoice(f, beat);
      return;
    }
    if (beat.kind === 'goto') {
      enterGoto(beat);
      return;
    }
    scheduleAdvance(beat.delayMs);
  };

  const awaitChoice = (f: Frame, beat: Beat): void => {
    cancelTimer();
    const alts = f.plan.alts.find((a) => a.path === String(beat.index));
    publish({ status: 'paused', awaitingChoice: alts ?? null });
  };

  const enterGoto = (beat: Beat): void => {
    const g = beat.goto;
    if (g === undefined) return;
    cancelTimer();
    const parent = frame();
    const target = g.file ?? parent.file;
    const text = textOf(target);
    const { doc } = text === null ? { doc: null } : parsePDL(text);
    const flow =
      doc === null
        ? null
        : (doc.flows.find((fl) => fl.id === g.flow) ?? doc.flows.find((fl) => fl.title === g.flow) ?? null);
    if (flow === null) {
      // dangling goto (validation flags it): pause instead of derailing
      publish({ status: 'paused' });
      return;
    }
    const plan = buildPlan({ doc: doc as NonNullable<typeof doc>, flow, choices: choices.current });
    if (g.file !== undefined && g.file !== parent.file) openFile(g.file);
    stack.current.push({
      plan,
      index: 0,
      file: target,
      returnTo: parent.index,
      retHere: g.ret === 'here',
    });
    publish({ breadcrumb: stack.current.slice(0, -1).map((fr) => fr.plan.flowTitle) });
    runBeat();
  };

  const scheduleAdvance = (ms: number): void => {
    cancelTimer();
    timer.current = clock.delay(() => {
      timer.current = null;
      advance();
    }, ms);
  };

  /** Move forward one beat (auto-advance or step±), handling frames/ends. */
  const advance = (): void => {
    const f = frame();
    if (f.index + 1 >= f.plan.beats.length) finishFrame();
    else {
      f.index += 1;
      runBeat();
    }
  };

  const finishFrame = (): void => {
    const done = stack.current.pop() as Frame;
    if (stack.current.length === 0) {
      cancelTimer();
      animator.stop();
      publish({ status: 'ended', narration: done.plan.flowTitle, breadcrumb: [], progress: progressOf(done) });
      return;
    }
    const parent = frame();
    if (done.retHere) {
      parent.index = done.returnTo;
      publish({ breadcrumb: stack.current.slice(0, -1).map((fr) => fr.plan.flowTitle) });
      runBeat();
      // 'return here' = loop checkpoint: replay the goto beat, then pause
      cancelTimer();
      publish({ status: 'paused' });
      return;
    }
    parent.index = done.returnTo;
    publish({ breadcrumb: stack.current.slice(0, -1).map((fr) => fr.plan.flowTitle) });
    advance(); // resume after the goto step
  };

  const start = useCallback(
    (file: string, flowKey: string) => {
      cancelTimer();
      animator.stop();
      stack.current = [];
      choices.current = {};
      parked.current = -1;
      camera.save({ x: 0, y: 0, k: 1 }); // owner passes the real viewport via snapTo? no — see below
      const text = textOf(file);
      const { doc } = text === null ? { doc: null } : parsePDL(text);
      const flow =
        doc === null
          ? null
          : (doc.flows.find((fl) => fl.id === flowKey) ?? doc.flows.find((fl) => fl.title === flowKey) ?? null);
      if (doc === null || flow === null) return;
      const plan = buildPlan({ doc, flow });
      stack.current.push({ plan, index: 0, file, returnTo: -1, retHere: false });
      setState({ ...EMPTY, status: 'playing' });
      runBeat();
    },
    [animator, camera, clock, textOf],
  );

  const stepTo = useCallback(
    (index1: number) => {
      if (stack.current.length === 0) return;
      cancelTimer();
      const f = frame();
      f.index = Math.max(0, Math.min(f.plan.beats.length - 1, index1 - 1));
      publish({ status: 'paused' });
      runBeat();
      cancelTimer(); // stepping parks (no auto-advance)
      publish({ status: 'paused' });
    },
    [clock],
  );

  const choose = useCallback(
    (branchIndex: number) => {
      const f = frame();
      const beat = f.plan.beats[f.index];
      if (beat?.kind !== 'alt') return;
      choices.current[String(beat.index)] = branchIndex;
      const newPlan = buildPlan({ doc: f.plan.docRef, flow: f.plan.flowRef, choices: choices.current });
      f.plan = newPlan;
      publish({ awaitingChoice: null, status: 'playing' });
      advance();
    },
    [clock],
  );

  const restart = useCallback(() => {
    choices.current = {};
    const f = frame();
    f.index = 0;
    setState({ ...EMPTY, status: 'playing' });
    runBeat();
  }, [clock]);

  const pause = useCallback(() => {
    cancelTimer();
    publish({ status: 'paused' });
  }, [clock]);

  const resume = useCallback(() => {
    const f = frame();
    const beat = f.plan.beats[f.index];
    if (beat === undefined) return;
    publish({ status: 'playing' });
    scheduleAdvance(beat.delayMs);
  }, [clock]);

  const exit = useCallback(() => {
    cancelTimer();
    animator.stop();
    camera.restoreSaved();
    stack.current = [];
    setState(EMPTY);
  }, [animator, camera, clock]);

  return {
    state,
    start,
    exit,
    pause,
    resume,
    restart,
    stepTo,
    choose,
    /** Owner updates the rect provider (canvas snapshot → world rects). */
    setRectProvider(r: FlowRects): void {
      rectsRef.current = r;
    },
  };
}
