{"content":"// SPDX-License-Identifier: GPL-3.0-only
// Play-mode transport (M5-WP5, PLAN §7; SPEC FR-F2/F3): drives the
// FlowAnimator + CameraController along a playback plan. Owns the beat index,
// alt-branch choices, goto frame stack (cross-file, FR-F2), narration text,
// and the auto-advance timer — all timing through the injected Clock, all
// visuals through the injected animator/camera (deterministic tests).
//
// Frame stack: goto pushes { plan, index, file, returnTo, retHere }; finishing
// a frame pops — `return end` (default) resumes AFTER the goto step, `return
// here` replays the goto beat's visual once (loop checkpoint) and pauses
// (FILE-FORMAT §6; documented in M5.md).
import { useCallback, useRef, useState } from 'preact/hooks';
import { buildPlan, type AltInfo, type FlowResolver, type PlaybackPlan } from '../../engine/flows/plan';
import { parsePDL } from '../../engine/format/parser';
import type { Beat, BeatCtx } from '../../engine/anim/engine';
import type { CameraController } from '../../engine/anim/camera';
import type { Clock } from '../../engine/anim/ports';
import type { Rect, Transform } from '../../engine/render/viewport';
import type { Doc, Flow } from '../../engine/model/types';

export interface FlowRects {
  rectOf(id: string): Rect | null;
}

export interface FlowPlayerDeps {
  /** File text lookup (workspace adapter); null when the file is absent. */
  textOf(path: string): string | null;
  /** Navigate to a file (goto cross-file). */
  openFile(path: string): void;
  animator: BeatPlayer;
  camera: CameraCam;
  clock: Clock;
  /** Pre-play viewport (saved for exit-restore, glide start point). */
  currentViewport(): Transform;
}

/** Narrow ports (real FlowAnimator/CameraController satisfy these). */
export interface BeatPlayer {
  play(beat: Beat, ctx: BeatCtx): void;
  stop(): void;
}
export interface CameraCam {
  focus(rects: Rect[], current: Transform): void;
  save(t: Transform): void;
  restoreSaved(): void;
}

interface Frame {
  plan: PlaybackPlan;
  doc: Doc;
  flow: Flow;
  index: number; // 0-based
  file: string;
  /** Parent plan index of the goto beat that pushed this frame (-1 = root). */
  returnTo: number;
  retHere: boolean;
}

export interface FlowPlayerState {
  status: 'idle' | 'playing' | 'paused' | 'ended';
  narration: string;
  breadcrumb: string[]; // titles of the frames above the current one
  awaitingChoice: AltInfo | null;
  progress: { index: number; total: number } | null;
}

const EMPTY: FlowPlayerState = {
  status: 'idle',
  narration: '',
  breadcrumb: [],
  awaitingChoice: null,
  progress: null,
};

export function useFlowPlayer(deps: FlowPlayerDeps) {
  const { textOf, openFile, animator, camera, clock, currentViewport } = deps;
  const [state, setState] = useState<FlowPlayerState>(EMPTY);
  const stack = useRef<Frame[]>([]);
  const choices = useRef<Record<string, number>>({});
  const timer = useRef<number | null>(null);
  const rectsRef = useRef<FlowRects>({ rectOf: () => null });

  const cancelTimer = (): void => {
    if (timer.current !== null) clock.cancel(timer.current);
    timer.current = null;
  };

  const frame = (): Frame => {
    const f = stack.current.at(-1);
    if (f === undefined) throw new Error('playback frame stack empty');
    return f;
  };

  const publish = (patch: Partial<FlowPlayerState>): void => {
    setState((s) => ({ ...s, ...patch }));
  };

  const breadcrumbOf = (): string[] =>
    stack.current.slice(0, -1).map((f) => f.plan.flowTitle);

  /** Parse `text`, find the flow by id or title. */
  const findFlow = (
    text: string | null,
    key: string,
  ): { doc: Doc; flow: Flow } | null => {
    const { doc } = text === null ? { doc: null } : parsePDL(text);
    if (doc === null) return null;
    const flow =
      doc.flows.find((fl) => fl.id === key) ?? doc.flows.find((fl) => fl.title === key) ?? null;
    return flow === null ? null : { doc, flow };
  };

  /** Execute the current frame's beat. `nav=false` skips goto navigation. */
  const runBeat = (nav = true): void => {
    const f = frame();
    const beat = f.plan.beats[f.index];
    if (beat === undefined) return;
    animator.play(beat, rectsRef.current);
    camera.focus(
      beat.actors.map((id) => rectsRef.current.rectOf(id)).filter((r): r is Rect => r !== null),
      currentViewport(),
    );
    publish({
      narration: beat.title,
      progress: { index: f.index + 1, total: f.plan.beats.length },
      awaitingChoice: null,
    });
    if (nav && beat.kind === 'alt') {
      awaitChoice(f, beat);
    } else if (nav && beat.kind === 'goto') {
      enterGoto(f, beat);
    } else {
      scheduleAdvance(beat.delayMs);
    }
  };

  const awaitChoice = (f: Frame, beat: Beat): void => {
    cancelTimer();
    const alts = f.plan.alts.find((a) => a.path === String(beat.index)) ?? null;
    publish({ status: 'paused', awaitingChoice: alts });
  };

  const enterGoto = (parent: Frame, beat: Beat): void => {
    const g = beat.goto;
    if (g === undefined) return;
    cancelTimer();
    const target = g.file ?? parent.file;
    const found = findFlow(textOf(target), g.flow);
    if (found === null) {
      publish({ status: 'paused' }); // dangling goto (validation flags it)
      return;
    }
    const plan = buildPlan({
      doc: found.doc,
      flow: found.flow,
      choices: choices.current,
      resolveFlow: g.file === undefined ? sameFileResolver(parent) : undefined,
    });
    if (g.file !== undefined && g.file !== parent.file) openFile(g.file);
    stack.current.push({
      plan,
      doc: found.doc,
      flow: found.flow,
      index: 0,
      file: target,
      returnTo: parent.index,
      retHere: g.ret === 'here',
    });
    publish({ breadcrumb: breadcrumbOf() });
    runBeat();
  };

  /** Same-file goto titles resolve against the parent frame's doc. */
  const sameFileResolver = (f: Frame): FlowResolver => {
    return (file, key) => {
      if (file !== undefined) return null;
      const fl = f.doc.flows.find((x) => x.id === key) ?? f.doc.flows.find((x) => x.title === key);
      return fl === null || fl === undefined ? null : { title: fl.title ?? fl.id };
    };
  };

  const scheduleAdvance = (ms: number): void => {
    cancelTimer();
    timer.current = clock.delay(() => {
      timer.current = null;
      advance();
    }, ms);
  };

  const advance = (): void => {
    const f = frame();
    if (f.index + 1 >= f.plan.beats.length) finishFrame();
    else {
      f.index += 1;
      runBeat();
    }
  };

  const finishFrame = (): void => {
    const done = stack.current.pop();
    if (done === undefined || stack.current.length === 0) {
      cancelTimer();
      animator.stop();
      const last = done?.plan;
      publish({
        status: 'ended',
        narration: last === undefined ? '' : last.flowTitle,
        breadcrumb: [],
        progress: done === undefined ? null : { index: done.plan.beats.length, total: done.plan.beats.length },
      });
      return;
    }
    const parent = frame();
    parent.index = done.returnTo;
    publish({ breadcrumb: breadcrumbOf() });
    if (done.retHere) {
      runBeat(false); // replay the goto beat's visual, no re-navigation
      cancelTimer();
      publish({ status: 'paused' }); // loop checkpoint awaits transport
      return;
    }
    advance(); // resume after the goto step
  };

  const start = useCallback(
    (file: string, flowKey: string) => {
      cancelTimer();
      animator.stop();
      stack.current = [];
      choices.current = {};
      camera.save(currentViewport());
      const found = findFlow(textOf(file), flowKey);
      if (found === null) return;
      const plan = buildPlan({ doc: found.doc, flow: found.flow });
      stack.current.push({
        plan,
        doc: found.doc,
        flow: found.flow,
        index: 0,
        file,
        returnTo: -1,
        retHere: false,
      });
      setState({ ...EMPTY, status: 'playing' });
      runBeat();
    },
    [animator, camera, clock, textOf, currentViewport],
  );

  const stepTo = useCallback(
    (index1: number) => {
      if (stack.current.length === 0) return;
      cancelTimer();
      const f = frame();
      f.index = Math.max(0, Math.min(f.plan.beats.length - 1, index1 - 1));
      runBeat();
      cancelTimer(); // stepping parks: no auto-advance
      publish({ status: 'paused' });
    },
    [clock],
  );

  const choose = useCallback(
    (branchIndex: number) => {
      const f = frame();
      const beat = f.plan.beats[f.index];
      if (beat?.kind !== 'alt') return;
      choices.current[String(beat.index)] = branchIndex;
      f.plan = buildPlan({ doc: f.doc, flow: f.flow, choices: choices.current });
      publish({ awaitingChoice: null, status: 'playing' });
      advance();
    },
    [clock],
  );

  const restart = useCallback(() => {
    choices.current = {};
    const f = frame();
    f.index = 0;
    setState({ ...EMPTY, status: 'playing' });
    runBeat();
  }, [clock]);

  const pause = useCallback(() => {
    cancelTimer();
    publish({ status: 'paused' });
  }, [clock]);

  const resume = useCallback(() => {
    const f = frame();
    const beat = f.plan.beats[f.index];
    if (beat === undefined) return;
    publish({ status: 'playing' });
    scheduleAdvance(beat.delayMs);
  }, [clock]);

  const exit = useCallback(() => {
    cancelTimer();
    animator.stop();
    camera.restoreSaved();
    stack.current = [];
    setState(EMPTY);
  }, [animator, camera, clock]);

  return {
    state,
    start,
    exit,
    pause,
    resume,
    restart,
    stepTo,
    choose,
    /** Owner keeps the rect provider in sync with the canvas snapshot. */
    setRectProvider(r: FlowRects): void {
      rectsRef.current = r;
    },
  };
}
