+    parent.index = done.returnTo;
+    publish({ breadcrumb: breadcrumbOf() });
+    if (done.retHere) {
+      runBeat(false); // replay the goto beat's visual, no re-navigation
+      cancelTimer();
+      publish({ status: 'paused' }); // loop checkpoint awaits transport
+      return;
+    }
+    advance(); // resume after the goto step
+  };
