{"content":"// SPDX-License-Identifier: GPL-3.0-only
// M5-WP4 flow editor (FR-F1): sidebar "Flows" tab. Flow list with per-flow
// play, step tree (indented flat list), per-type inline inspectors, and
// structural ops (add/move/remove step, add branch/lane, add flow). All
// edits round-trip through retext() and surface as onChangeText(newText) —
// App forwards to code.machine.textChanged so the sync machine stays the
// single writer (D-M4-6). Takes narrow ports (textOf), no manager import.
import { useRef, useState } from 'preact/hooks';
import { parsePDL } from '../../engine/format/parser';
import type { Branch, Doc, Flow, FlowStep } from '../../engine/model/types';
import {
  addBranch,
  addFlow,
  addLane,
  appendStep,
  flatSteps,
  getAt,
  moveStep,
  newStep,
  patchStep,
  removeAt,
  retext,
  type FlatStep,
} from './flowDoc';

export interface FlowPaneProps {
  textOf(path: string): string | null;
  activePath: string | null;
  /** Bumped by the owner on every workspace emit; re-reads the text. */
  version: number;
  /** Persist a mutated document (App → machine.textChanged). */
  onChangeText(text: string): void;
  /** Start playback of a flow in the active file. */
  onPlay(flowKey: string): void;
}

interface Sel {
  flow: string; // flow id
  step: number[]; // path into the flow ([] = flow-level, nothing selected)
}

type Patch = (p: Partial<FlowStep>) => void;

interface InspectActions {
  patch: Patch;
  move: (d: -1 | 1) => void;
  remove: () => void;
  addBranch: () => void;
  addLane: () => void;
}

const KINDS: FlowStep['type'][] = [
  'intro',
  'msg',
  'process',
  'alt',
  'par',
  'goto',
  'info',
  'conclusion',
];

function Field(props: { label: string; value: string; onInput: (v: string) => void; testid: string }) {
  return (
    <label class="flow-field">
      <span class="flow-field-label">{props.label}</span>
      <input
        data-testid={props.testid}
        value={props.value}
        onInput={(e) => props.onInput((e.target as HTMLInputElement).value)}
      />
    </label>
  );
}

function TextFields({ step, patch }: { step: { text: string }; patch: Patch }) {
  return <Field label="Text" value={step.text} onInput={(v) => patch({ text: v })} testid="insp-text" />;
}

function MsgFields({ step, patch }: { step: Extract<FlowStep, { type: 'msg' }>; patch: Patch }) {
  return (
    <>
      <Field label="From" value={step.from} onInput={(v) => patch({ from: v })} testid="insp-from" />
      <Field label="To" value={step.to} onInput={(v) => patch({ to: v })} testid="insp-to" />
      <Field
        label="Label"
        value={step.label ?? ''}
        onInput={(v) => patch({ label: v === '' ? undefined : v })}
        testid="insp-label"
      />
      <label class="flow-field">
        <span class="flow-field-label">Flip</span>
        <input
          type="checkbox"
          data-testid="insp-flip"
          checked={step.flip === true}
          onChange={(e) => patch({ flip: (e.target as HTMLInputElement).checked || undefined })}
        />
      </label>
    </>
  );
}

function ProcessFields({ step, patch }: { step: Extract<FlowStep, { type: 'process' }>; patch: Patch }) {
  return (
    <>
      <Field label="Target" value={step.target} onInput={(v) => patch({ target: v })} testid="insp-target" />
      <Field
        label="Note"
        value={step.text ?? ''}
        onInput={(v) => patch({ text: v === '' ? undefined : v })}
        testid="insp-process-note"
      />
    </>
  );
}

function AltFields({ step, patch, addBranch }: { step: Extract<FlowStep, { type: 'alt' }>; patch: Patch; addBranch: () => void }) {
  return (
    <>
      <Field label="Label" value={step.label ?? ''} onInput={(v) => patch({ label: v === '' ? undefined : v })} testid="insp-alt-label" />
      {step.branches.map((b: Branch, i) => (
        <Field
          key={i}
          label={`Branch ${i + 1}`}
          value={b.label}
          onInput={(v) => {
            const branches = step.branches.map((bb, j) => (j === i ? { ...bb, label: v } : bb));
            patch({ branches } as Partial<FlowStep>);
          }}
          testid={`insp-branch-${i}`}
        />
      ))}
      <button type="button" data-testid="insp-branch-add" onClick={addBranch}>+ branch</button>
    </>
  );
}

function GotoFields({ step, patch }: { step: Extract<FlowStep, { type: 'goto' }>; patch: Patch }) {
  return (
    <>
      <Field label="File" value={step.file ?? ''} onInput={(v) => patch({ file: v === '' ? undefined : v })} testid="insp-goto-file" />
      <Field label="Flow" value={step.flow} onInput={(v) => patch({ flow: v })} testid="insp-goto-flow" />
      <label class="flow-field">
        <span class="flow-field-label">Return here</span>
        <input
          type="checkbox"
          data-testid="insp-goto-here"
          checked={step.ret === 'here'}
          onChange={(e) => patch({ ret: (e.target as HTMLInputElement).checked ? 'here' : undefined })}
        />
      </label>
    </>
  );
}

function StepInspector({ step, a }: { step: FlowStep; a: InspectActions }) {
  return (
    <div class="flow-inspector" data-testid="flow-inspector">
      <div class="flow-insp-head">
        <select
          data-testid="step-kind"
          value={step.type}
          onChange={(e) => a.patch(newStep((e.target as HTMLSelectElement).value as FlowStep['type']))}
        >
          {KINDS.map((k) => (
            <option key={k} value={k}>{k}</option>
          ))}
        </select>
        <button type="button" data-testid="step-up" onClick={() => a.move(-1)}>↑</button>
        <button type="button" data-testid="step-down" onClick={() => a.move(1)}>↓</button>
        <button type="button" data-testid="step-remove" onClick={a.remove}>✕</button>
      </div>
      {step.type === 'msg' ? (
        <MsgFields step={step} patch={a.patch} />
      ) : step.type === 'process' ? (
        <ProcessFields step={step} patch={a.patch} />
      ) : step.type === 'alt' ? (
        <>
          <AltFields step={step} patch={a.patch} addBranch={a.addBranch} />
          <button type="button" data-testid="insp-lane-add" style="display:none" onClick={a.addLane}>+ lane</button>
        </>
      ) : step.type === 'par' ? (
        <>
          <Field label="Label" value={step.label ?? ''} onInput={(v) => patchLabel(a.patch, v)} testid="insp-par-label" />
          <button type="button" data-testid="insp-lane-add" onClick={a.addLane}>+ lane</button>
        </>
      ) : step.type === 'goto' ? (
        <GotoFields step={step} patch={a.patch} />
      ) : (
        <TextFields step={step} patch={a.patch} />
      )}
    </div>
  );
}

function patchLabel(patch: Patch, v: string): void {
  patch({ label: v === '' ? undefined : v } as Partial<FlowStep>);
}

function stepTitle(s: FlowStep): string {
  if (s.type === 'msg') return s.label ?? `${s.from} → ${s.to}`;
  if (s.type === 'process') return s.target;
  if (s.type === 'alt' || s.type === 'par') return s.label ?? s.type;
  if (s.type === 'goto') return `→ ${s.file === undefined ? '' : `${s.file}#`}${s.flow}`;
  return s.text;
}

function StepList(props: { steps: FlatStep[]; sel: number[]; onSelect: (p: number[]) => void }) {
  return (
    <ol class="flow-steps" data-testid="flow-steps">
      {props.steps.map((fs, i) => {
        const active = fs.path.length === props.sel.length && fs.path.every((v, j) => v === props.sel[j]);
        return (
          <li key={fs.path.join('.')} class={`flow-step${active ? ' active' : ''}`}>
            <button
              type="button"
              data-testid={`step-${i}`}
              style={`padding-left: ${8 + fs.depth * 14}px`}
              onClick={() => props.onSelect(fs.path)}
            >
              <span class={`flow-step-kind kind-${fs.step.type}`}>{fs.step.type}</span>
              <span class="flow-step-title">{stepTitle(fs.step)}</span>
            </button>
          </li>
        );
      })}
    </ol>
  );
}

/** Resolve the holding list for a nested path (pairwise container/slot walk). */
function stepsAt(flow: Flow, path: number[]): FlowStep[] | null {
  let list: FlowStep[] = flow.steps;
  for (let i = 0; i + 1 < path.length; i += 2) {
    const owner = list[path[i]];
    const slot = path[i + 1];
    if (owner === undefined || slot === undefined) return null;
    if (owner.type === 'alt') {
      const b = owner.branches[slot];
      if (b === undefined) return null;
      list = b.steps;
    } else if (owner.type === 'par') {
      const lane = owner.lanes[slot];
      if (lane === undefined) return null;
      list = lane;
    } else {
      return null;
    }
  }
  return list;
}

/** Sidebar "Flows" tab: list flows, edit the selected one, play it. */
export function FlowPane(props: FlowPaneProps) {
  const [sel, setSel] = useState<Sel | null>(null);
  const addKindRef = useRef<HTMLSelectElement | null>(null);
  const text = props.activePath === null ? null : props.textOf(props.activePath);
  const doc: Doc | null = text === null ? null : parsePDL(text).doc;

  const apply = (fn: (d: Doc) => void): void => {
    if (text === null) return;
    const next = retext(text, fn);
    if (next !== null) props.onChangeText(next);
  };

  if (props.activePath === null || doc === null) {
    return (
      <div class="flow-pane" data-testid="flow-pane">
        <p class="muted" data-testid="flow-error">
          {props.activePath === null ? 'Open a file to edit flows.' : 'Active file has parse errors.'}
        </p>
      </div>
    );
  }

  const flow: Flow | null = sel === null ? null : (doc.flows.find((f) => f.id === sel.flow) ?? null);
  const step: FlowStep | null = sel !== null && flow !== null && sel.step.length > 0 ? getAt(flow, sel.step) : null;
  const flat = flow === null ? [] : flatSteps(flow);

  const mutateSel = (fn: (f: Flow, path: number[]) => void): void => {
    if (sel === null || sel.step.length === 0) return;
    apply((d) => {
      const f = d.flows.find((x) => x.id === sel.flow);
      if (f !== undefined) fn(f, sel.step);
    });
  };

  const actions: InspectActions = {
    patch: (p) => mutateSel((f, path) => patchStep(f, path, p)),
    move: (d) =>
      mutateSel((f, path) => {
        const i = path.at(-1);
        if (i !== undefined) moveStep(f, path, i + d);
      }),
    remove: () => mutateSel((f, path) => removeAt(f, path)),
    addBranch: () =>
      mutateSel((f, path) => addBranch(f, path, `option ${(step?.type === 'alt' ? step.branches.length : 0) + 1}`)),
    addLane: () => mutateSel((f, path) => addLane(f, path)),
  };

  const addStep = (): void => {
    if (sel === null) return;
    const kind = (addKindRef.current?.value ?? 'intro') as FlowStep['type'];
    apply((d) => {
      const f = d.flows.find((x) => x.id === sel.flow);
      if (f !== undefined) appendStep(f, newStep(kind));
    });
  };

  const addFlowRow = (): void => {
    const seq = doc.flows.length + 1;
    apply((d) => addFlow(d, 'New flow', seq));
    setSel({ flow: `flow${seq}`, step: [] });
  };

  return (
    <div class="flow-pane" data-testid="flow-pane">
      <ul class="flow-list" data-testid="flow-list">
        {doc.flows.map((f) => (
          <li key={f.id} class={sel !== null && sel.flow === f.id ? 'active' : ''}>
            <button type="button" data-testid={`flow-row-${f.id}`} onClick={() => setSel({ flow: f.id, step: [] })}>
              {f.title ?? f.id}
            </button>
            <button type="button" title="Play" data-testid={`flow-play-${f.id}`} onClick={() => props.onPlay(f.id)}>
              ▶
            </button>
          </li>
        ))}
      </ul>
      <button type="button" data-testid="flow-add" onClick={addFlowRow}>+ flow</button>
      {flow !== null && (
        <>
          <StepList steps={flat} sel={sel.step} onSelect={(p) => setSel({ flow: sel.flow, step: p })} />
          <div class="flow-stepbar">
            <select ref={addKindRef} data-testid="step-add-kind" defaultValue="msg">
              {KINDS.map((k) => (
                <option key={k} value={k}>{k}</option>
              ))}
            </select>
            <button type="button" data-testid="step-add" onClick={addStep}>+ step</button>
          </div>
          {step !== null && <StepInspector step={step} a={actions} />}
        </>
      )}
    </div>
  );
}
