/** Resolve the holding list for a nested path (pairwise container/slot walk). */
function stepsAt(flow: Flow, path: number[]): FlowStep[] | null {
  let list: FlowStep[] = flow.steps;
  for (let i = 0; i + 1 < path.length; i += 2) {
    const owner = list[path[i]];
    const slot = path[i + 1];
    if (owner === undefined || slot === undefined) return null;
    if (owner.type === 'alt') {
      const b = owner.branches[slot];
      if (b === undefined) return null;
      list = b.steps;
    } else if (owner.type === 'par') {
    setSel({ flow: `flow${seq}`, step: [] });
