/** Sidebar "Flows" tab: list flows, edit the selected one, play it. */
export function FlowPane(props: FlowPaneProps) {
  const [sel, setSel] = useState<Sel | null>(null);
  const addKindRef = useRef<HTMLSelectElement | null>(null);
  const text = props.activePath === null ? null : props.textOf(props.activePath);
  const doc: Doc | null = text === null ? null : parsePDL(text).doc;

  const apply = (fn: (d: Doc) => void): void => {
    if (text === null) return;
    const next = retext(text, fn);
    if (next !== null) props.onChangeText(next);
  };

  if (props.activePath === null || doc === null) {
    return (
      <div class="flow-pane" data-testid="flow-pane">
        <p class="muted" data-testid="flow-error">
          {props.activePath === null ? 'Open a file to edit flows.' : 'Active file has parse errors.'}
        </p>
      </div>
    );
  }

  const flow: Flow | null = sel === null ? null : (doc.flows.find((f) => f.id === sel.flow) ?? null);
  const selStep = sel?.step ?? [];
  const selFlow = sel?.flow ?? '';
  const step: FlowStep | null = sel !== null && flow !== null && sel.step.length > 0 ? getAt(flow, sel.step) : null;
  const flat = flow === null ? [] : flatSteps(flow);

  const mutateSel = (fn: (f: Flow, path: number[]) => void): void => {
    if (sel === null || sel.step.length === 0) return;
    apply((d) => {
      const f = d.flows.find((x) => x.id === sel.flow);
      if (f !== undefined) fn(f, sel.step);
    });
  };

  const actions: InspectActions = {
    patch: (p) => mutateSel((f, path) => patchStep(f, path, p)),
    move: (d) =>
      mutateSel((f, path) => {
        const i = path.at(-1);
        if (i !== undefined) moveStep(f, path, i + d);
      }),
    remove: () => mutateSel((f, path) => removeAt(f, path)),
    addBranch: () =>
      mutateSel((f, path) => addBranch(f, path, `option ${(step?.type === 'alt' ? step.branches.length : 0) + 1}`)),
    addLane: () => mutateSel((f, path) => addLane(f, path)),
  };

  const addStep = (): void => {
    if (sel === null) return;
    const kind = (addKindRef.current?.value ?? 'intro') as FlowStep['type'];
    // Seed msg/process with real object ids so the printed step parses.
    const a0 = doc.objects[0]?.id ?? 'x';
    const a1 = doc.objects[1]?.id ?? a0;
    apply((d) => {
      const f = d.flows.find((x) => x.id === sel.flow);
      if (f === undefined) return;
      const s = newStep(kind);
      if (s.type === 'msg') {
        s.from = a0;
        s.to = a1;
      } else if (s.type === 'process') {
        s.target = a0;
      }
      appendStep(f, s);
    });
  };

  const addFlowRow = (): void => {
    const seq = doc.flows.length + 1;
    apply((d) => addFlow(d, 'New flow', seq));
    setSel({ flow: `flow${seq}`, step: [] });
  };

  return (
    <div class="flow-pane" data-testid="flow-pane">
      <ul class="flow-list" data-testid="flow-list">
        {doc.flows.map((f) => (
          <li key={f.id ?? f.title} class={selFlow === (f.id ?? f.title) ? 'active' : ''}>
            <button
              type="button"
              data-testid={`flow-row-${f.id ?? f.title}`}
              onClick={() => setSel({ flow: f.id ?? f.title ?? '', step: [] })}
            >
              {f.title ?? f.id}
            </button>
            <button
              type="button"
              title="Play"
              data-testid={`flow-play-${f.id ?? f.title}`}
              onClick={() => props.onPlay(f.id ?? f.title ?? '')}
            >
              ▶
            </button>
          </li>
        ))}
      </ul>
      <button type="button" data-testid="flow-add" onClick={addFlowRow}>+ flow</button>
      {flow !== null && (
        <>
          <StepList steps={flat} sel={selStep} onSelect={(p) => setSel({ flow: selFlow, step: p })} />
          <div class="flow-stepbar">
            <select ref={addKindRef} data-testid="step-add-kind" defaultValue="msg">
              {KINDS.map((k) => (
                <option key={k} value={k}>{k}</option>
              ))}
            </select>
            <button type="button" data-testid="step-add" onClick={addStep}>+ step</button>
          </div>
          {step !== null && <StepInspector step={step} a={actions} />}
        </>
      )}
    </div>
  );
}

