      {flow !== null && (
        <FlowDetail
          flat={flat}
          selStep={selStep}
          selFlow={selFlow}
          step={step}
          addKindRef={addKindRef}
          onPickStep={(p) => setSel({ flow: selFlow, step: p })}
          onAddStep={addStep}
        />
      )}
    </div>
  );
